      "title": "The Dangerous Healer",
      "start_block": "B058",
      "end_block": "B065",
      "hook": "Alexander sternly warns Juliana that her good deed will bring danger, while she defiantly states a child's life matters more.",
      "cliffhanger": "Juliana declares they will face the coming danger together, cutting right as Alexander looks at her with intense concern.",
      "why": "Creates immediate conflict between safety and morality, ending on a romantic vow of unity against an unseen threat.",
      "context_gap": "None. The viewer sees a husband warning his wife about gossip, and she refuses to back down."
    },
    {
      "title": "The Duke's Secret Revealed",
      "start_block": "B074",
      "end_block": "B089",
      "hook": "The Former Groom urgently whispers to the Blond Nobleman that a war veteran resembles the late Duke.",
      "cliffhanger": "The Blond Nobleman's eye widens in terror as he realizes the rumor might be true, staring into the fire in panic.",
      "why": "Delivers a high-stakes identity reveal hook immediately, escalating from casual gossip to life-or-death paranoia.",
      "context_gap": "A stranger won't know who the 'late Duke' is or why the villain is so afraid, but understands the stakes are huge."
    },
    {
      "title": "Life or Death Remedy",
      "start_block": "B012",
      "end_block": "B044",
      "hook": "A frantic mother begs for help as Juliana rushes to examine a feverish child, with Alexander watching anxiously.",
      "cliffhanger": "The mother screams that the remedy isn't working, and Juliana holds up a finger demanding patience just as hope seems lost.",
      "why": "Starts with high emotional urgency and a life-or-death situation, ending on a moment of suspended tension before the cure works.",
      "context_gap": "None. The viewer instantly understands a sick child needs a cure and the healer is hesitating."
    }
  ],
  "moments": [
    {
      "start_block": "B003",
      "end_block": "B006",
      "kind": "hook",
      "description": "Frantic pounding on the door interrupts a quiet evening, followed by Alexander ordering Juliana to stay back."
    },
    {
      "start_block": "B078",
      "end_block": "B081",
      "kind": "reveal",
      "description": "The Former Groom reveals the man has the same scar as the Duke, causing the Blond Nobleman to snap and demand to know where."
    },
    {
      "start_block": "B087",
      "end_block": "B089",
      "kind": "cliffhanger",
      "description": "The Blond Nobleman stares into the fire, whispering 'Impossible' as dread consumes him."
    },
    {
      "start_block": "B056",
      "end_block": "B059",
      "kind": "emotional",
      "description": "The grateful mother vows to tell the village what Juliana did, immediately triggering Alexander's fear of exposure."
    }
